def cartesian_product(a, b):
    result = []
    for item_a in a:
        for item_b in b:
            result.append((item_a, item_b))
    return result

def cartesian_product_of_shape(dimentions, result=None):
    if result is None:
        result = [()]

    if not dimentions:
        return result

    current_dimension = dimentions[0]
    remaining_dimensions = dimentions[1:]

    new_result = []
    for i in range(current_dimension):
        for path_tuple in result:
            new_result.append(path_tuple + (i,))

    return cartesian_product_of_shape(remaining_dimensions, new_result)
